package vn.covie.outbox.application; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import vn.covie.shared.outbox.*; import vn.covie.shared.time.AppClock; import vn.covie.realtime.SseSignal;
@Service public class OutboxTransactionalProcessor {private final OutboxEventRepository events;private final OutboxHandlerRegistry registry;private final AppClock clock;public OutboxTransactionalProcessor(OutboxEventRepository e,OutboxHandlerRegistry r,AppClock c){events=e;registry=r;clock=c;}@Transactional(propagation=Propagation.REQUIRES_NEW)public OutboxProcessingResult processOneTransaction(){var maybe=events.lockNextDue(clock.now());if(maybe.isEmpty())return OutboxProcessingResult.none();var event=maybe.get();try{List<SseSignal> signals=registry.handlersFor(event.getEventType()).stream().flatMap(h->h.handle(new OutboxEventContext(event.getId(),event.getEventType(),event.getAggregateType(),event.getAggregateId(),event.getPayload(),event.getOccurredAt())).stream()).toList();event.markPublished(clock.now());return new OutboxProcessingResult(event.getId(),signals);}catch(Throwable error){throw new OutboxProcessingException(event.getId(),error);}}}
